    Bug 2033655 - Tick the net.thunderbird default handler checkbox by default. r=tobyp

    Since we're opening this dialog when not the default handler, we should check the checkbox.

    Differential Revision: https://phabricator.services.mozilla.com/D299467

diff --git a/mail/base/content/systemIntegrationDialog.js b/mail/base/content/systemIntegrationDialog.js
index b5e4c70e96d..5646c68e47a 100644
--- a/mail/base/content/systemIntegrationDialog.js
+++ b/mail/base/content/systemIntegrationDialog.js
@@ -91,11 +91,12 @@ var gSystemIntegrationDialog = {
       this._calendarCheckbox.removeAttribute("tooltiptext");
     }

+    this._netThunderbirdCheckbox.disabled = this._shellSvc.isDefaultClient(
+      false,
+      this._shellSvc.NET_THUNDERBIRD
+    );
     this._netThunderbirdCheckbox.checked =
-      this._netThunderbirdCheckbox.disabled = this._shellSvc.isDefaultClient(
-        false,
-        this._shellSvc.NET_THUNDERBIRD
-      );
+      !calledFromPrefs || this._netThunderbirdCheckbox.disabled;
     if (!this._netThunderbirdCheckbox.disabled) {
       this._netThunderbirdCheckbox.removeAttribute("tooltiptext");
     }
